CREATE TABLE public.gym_owner_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), gym_id uuid NOT NULL REFERENCES public.gyms(id), event_key text, type text NOT NULL, description text NOT NULL, page text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(gym_id,event_key));
GRANT SELECT ON public.gym_owner_events TO authenticated; GRANT ALL ON public.gym_owner_events TO service_role;
ALTER TABLE public.gym_owner_events ENABLE ROW LEVEL SECURITY;
CREATE POLICY gym_owner_events_read ON public.gym_owner_events FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.user_roles WHERE gym_id=gym_owner_events.gym_id AND user_id=auth.uid() AND role='Owner'));
CREATE TABLE public.gym_owner_event_status(event_id uuid NOT NULL REFERENCES public.gym_owner_events(id), user_id uuid NOT NULL, read_at timestamptz, dismissed_at timestamptz, PRIMARY KEY(event_id,user_id));
GRANT SELECT,INSERT,UPDATE ON public.gym_owner_event_status TO authenticated; GRANT ALL ON public.gym_owner_event_status TO service_role;
ALTER TABLE public.gym_owner_event_status ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_gym_event_status ON public.gym_owner_event_status FOR ALL TO authenticated USING(user_id=auth.uid() AND EXISTS(SELECT 1 FROM public.gym_owner_events e JOIN public.user_roles r ON r.gym_id=e.gym_id WHERE e.id=event_id AND r.user_id=auth.uid() AND r.role='Owner')) WITH CHECK(user_id=auth.uid() AND EXISTS(SELECT 1 FROM public.gym_owner_events e JOIN public.user_roles r ON r.gym_id=e.gym_id WHERE e.id=event_id AND r.user_id=auth.uid() AND r.role='Owner'));
CREATE FUNCTION public.capture_gym_owner_event() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE t text; msg text; p text; BEGIN
IF TG_OP='DELETE' THEN IF OLD.kind='sessions' THEN INSERT INTO public.gym_owner_events(gym_id,type,description,page) VALUES(OLD.gym_id,'Session',coalesce(OLD.data->>'name','Client')||' · Session cancelled ('||coalesce(OLD.data->>'date','')||')','/sessions'); END IF; RETURN OLD; END IF;
IF TG_OP='UPDATE' AND NEW.data IS NOT DISTINCT FROM OLD.data THEN RETURN NEW; END IF;
IF NEW.kind='members' THEN IF TG_OP='INSERT' THEN t='Membership';msg=coalesce(NEW.data->>'name','Client')||' · Membership created';p='/members'; ELSIF NEW.data->>'expiry' IS DISTINCT FROM OLD.data->>'expiry' OR NEW.data->>'start' IS DISTINCT FROM OLD.data->>'start' OR NEW.data->>'plan' IS DISTINCT FROM OLD.data->>'plan' THEN t='Membership';msg=coalesce(NEW.data->>'name','Client')||' · Membership renewed or updated';p='/members'; END IF;
ELSIF NEW.kind IN ('attendance','staffAttendance') AND TG_OP='INSERT' THEN t='Attendance';msg=coalesce(NEW.data->>'name','Client')||' · Check-in on '||coalesce(NEW.data->>'date','')||' at '||coalesce(NEW.data->>'time','');p='/attendance';
ELSIF NEW.kind='sessions' THEN t='Session';msg=coalesce(NEW.data->>'name','Client')||' · Session '||CASE WHEN TG_OP='INSERT' THEN 'created' ELSE 'updated' END||' on '||coalesce(NEW.data->>'date','');p='/sessions';
ELSIF NEW.kind='transactions' AND coalesce((NEW.data->>'entered')::boolean,false) AND NOT coalesce((NEW.data->>'deleted')::boolean,false) THEN t=CASE WHEN (NEW.data->>'amount')::numeric<0 THEN 'Expense' ELSE 'Payment' END;msg=coalesce(NEW.data->>'name','Invoice')||' · '||CASE WHEN TG_OP='INSERT' THEN 'Recorded' ELSE 'Updated' END||' EGP '||abs((NEW.data->>'amount')::numeric)::text||' on '||coalesce(NEW.data->>'date','');p='/finance';
ELSIF NEW.kind='products' AND TG_OP='UPDATE' AND (NEW.data->>'sales')::numeric>coalesce((OLD.data->>'sales')::numeric,0) THEN t='Product sale';msg=coalesce(NEW.data->>'name','Product')||' · '||((NEW.data->>'sales')::numeric-coalesce((OLD.data->>'sales')::numeric,0))::text||' units sold';p='/products'; END IF;
IF t IS NOT NULL THEN INSERT INTO public.gym_owner_events(gym_id,type,description,page) VALUES(NEW.gym_id,t,msg,p); END IF; RETURN NEW; END $$;
CREATE TRIGGER capture_gym_owner_event AFTER INSERT OR UPDATE OR DELETE ON public.gym_records FOR EACH ROW EXECUTE FUNCTION public.capture_gym_owner_event();
CREATE FUNCTION public.capture_gym_invitation_event() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.status IS DISTINCT FROM OLD.status AND NEW.status IN ('Accepted','Declined') THEN INSERT INTO public.gym_owner_events(gym_id,event_key,type,description,page) VALUES(NEW.gym_id,'invitation-response:'||NEW.id,'Staff invitation',NEW.full_name||' · Invitation '||lower(NEW.status)||' ('||NEW.role||')','/staff') ON CONFLICT(gym_id,event_key) DO NOTHING; END IF; RETURN NEW; END $$;
CREATE TRIGGER capture_gym_invitation_event AFTER UPDATE ON public.staff_invitations FOR EACH ROW EXECUTE FUNCTION public.capture_gym_invitation_event();
CREATE FUNCTION public.refresh_gym_expiration_events(g uuid, day date) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND gym_id=g AND role='Owner') THEN RAISE EXCEPTION 'Gym owner account required'; END IF; IF day<current_date-1 OR day>current_date+1 THEN RAISE EXCEPTION 'Invalid date'; END IF; INSERT INTO public.gym_owner_events(gym_id,event_key,type,description,page) SELECT g,'expiry:'||id||':'||(data->>'expiry')||':'||CASE WHEN (data->>'expiry')::date<day THEN 'expired' ELSE 'approaching' END,'Membership expiration',coalesce(data->>'name','Client')||CASE WHEN (data->>'expiry')::date<day THEN ' · Membership expired on ' ELSE ' · Membership expires on ' END||(data->>'expiry'),'/members' FROM public.gym_records WHERE gym_id=g AND kind='members' AND (data->>'expiry')::date<=day+7 ON CONFLICT(gym_id,event_key) DO NOTHING; END $$;
REVOKE ALL ON FUNCTION public.refresh_gym_expiration_events(uuid,date) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.refresh_gym_expiration_events(uuid,date) TO authenticated;